snippet_css:
:root{
  --bg: #6A4C93;
  --fg: #FFFFFF;
  --muted: #F6EAFF;
  --surface: #3A2A57;
  --border: #111111;
  --accent: #FFD60A;
  --accent-fg: #111111;
  --radius: 0 28px 0 28px;
  --radius-sm: 0 18px 0 18px;
  --shadow: 8px 8px 0 #111111;
  --btn-shadow: 6px 6px 0 #111111;
  --art-bg: linear-gradient(135deg,#E63946,#6A4C93 55%,#2A9D8F);
  --media-bg: linear-gradient(45deg,#FFD60A 0 14px,#FFFFFF 14px 28px);
  --cta-bg: #3A2A57;
  --input-bg: #2E2246;
  --ok: #9DF3B8;
  --warn: #FFC2D1;
  --font-display: 'Bricolage Grotesque','Noto Sans TC',sans-serif;
  --font-body: 'Bricolage Grotesque','Noto Sans TC',sans-serif;
  --font-mono: 'Rubik Mono One',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

